  function seasonLabel(g) { var y=(g&&g.startYear||2026)+(g?g.season-1:0); return y+'–'+String(y+1).slice(-2); }
  function activeTeam() { return current.game ? team(current.game.team) : team(current.selected); }
  function setNotice(message,bad) { var n=$('notice-bar'); n.hidden=false; n.textContent=message; n.style.borderColor=bad?'rgba(255,107,104,.5)':''; n.style.color=bad?'#ffb0aa':'';var global=$('global-message');global.hidden=current.phase==='office';global.textContent=message;global.style.color=bad?'#ffb0aa':''; }
  function clearNotice(){var n=$('notice-bar'),global=$('global-message');if(n){n.hidden=true;n.textContent='';n.style.borderColor='';n.style.color='';}if(global){global.hidden=true;global.textContent='';global.style.color='';}}
  /* ===== SAVE SYSTEM V2: compact saves in IndexedDB (localStorage fallback) ===== */
