  function saveSummary(g,savedAt){var r=g.record||{};return {team:g.team,season:seasonLabel(g),record:{w:r.w||0,l:r.l||0,otl:r.otl||0},day:g.day||0,stage:g.stage||'',savedAt:savedAt};}
