  // Auto-save: every call marks the franchise dirty; the write happens shortly after the burst of changes ends.
  function persist(){if(!current.game)return;saveState.dirty=true;if(saveState.timer)clearTimeout(saveState.timer);saveState.timer=setTimeout(function(){saveState.timer=null;flushSave();},700);}
  function persistOnLeave(){if(!current.game||!(saveState.dirty||saveState.timer))return;flushSave();try{var savedAt=Date.now(),json=JSON.stringify(compactGameForSave(current.game));if(json.length<4500000)writeLocalSave(json,savedAt,saveSummary(current.game,savedAt),null);}catch(e){}}
  window.addEventListener('pagehide',persistOnLeave);
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden'&&current.game&&(saveState.dirty||saveState.timer))flushSave();});
  function parseLocalSave(raw){if(!raw)return null;try{return JSON.parse(raw);}catch(e){return null;}}
  function gameFromLocalRecord(p){if(!p)return Promise.resolve(null);if(p.cfoSave){if(p.encoding==='gzip-base64')return saveGunzip(saveFromBase64(p.data)).then(function(t){return {game:JSON.parse(t),where:'localStorage',savedAt:p.savedAt};});return Promise.resolve({game:p.game,where:'localStorage',savedAt:p.savedAt});}return Promise.resolve({game:p,where:'localStorage (older save)',savedAt:0});}
