  function capFloorCard(g){var gap=capFloorGap(g);return '<div class="stat-card cap-floor-card"><span>CAP FLOOR</span><strong>'+shortMoney(capFloorFor(g))+'</strong>'+(gap>0?'<small style="color:var(--red)">'+shortMoney(gap)+' BELOW FLOOR</small>':'<small>FLOOR MET</small>')+'</div>';}
  function capFloorWarning(g){var gap=capFloorGap(g);if(gap<=0)return '';return '<p class="panel-subtitle cap-floor-warning" style="color:var(--red)">'+esc(team(g.team).name)+' payroll ('+shortMoney(capUsed(g))+') is '+shortMoney(gap)+' below the '+shortMoney(capFloorFor(g))+' cap floor (the floor sits $20M under the ceiling). Add salary through free agency, trades or re-signings.</p>';}
