    if(g.stage==='regular'&&g.day<seasonGameCount(g))return 'Play next game';
    if(g.stage==='regular'&&g.day>=seasonGameCount(g))return g.mode==='franchise'?'Start the playoffs':'Finish the season';
    if(g.stage==='playoffs')return 'Simulate next round';
    if(g.stage==='offseason'){var phase=g.offseason&&g.offseason.phase||'phones';return phase==='phones'?'Offseason briefing':phase==='draft'?'Open draft & prospects':phase==='free-agency'?'Open free agency':phase==='signings'?'Resolve draft rights':g.season<25?'Begin '+seasonLabel({season:g.season+1})+' season':'Complete 25-year run';}
    return 'Season complete';
