  function freeAgentInterest(g,p){var affinity=p.teamAffinity||{},user=Number(affinity[g.team]);if(!Number.isFinite(user))user=38+Math.floor(seededRandom('fa-interest|'+p.id+'|'+g.team)()*45);var rivals=teams.filter(function(t){return t.id!==g.team;}).map(function(t){var value=Number(affinity[t.id]);if(!Number.isFinite(value))value=28+Math.floor(seededRandom('fa-interest|'+p.id+'|'+t.id)()*63);if(p.preference==='Contender'&&primeContender(g,t.id))value+=12;if(g.philosophy==='youth'&&p.age<25&&leagueClub(g,t.id).plan==='rebuild')value+=8;return {id:t.id,name:t.name,value:clamp(value,10,98)};}).sort(function(a,b){return b.value-a.value;}).slice(0,3);return {user:clamp(user,8,98),rivals:rivals};}
  /* ===== FA MARKET REALISM (v3.1): value-based asks, max/min contract, RFA tenders, late market ===== */
  function leagueMinSalaryFor(cap){return Math.max(775000,Math.round(775000*(Number(cap)||104000000)/95500000/25000)*25000);}
  function leagueMinSalary(g){return leagueMinSalaryFor(Number(g&&g.cap)||104000000);}
