    var goals=[];sides.forEach(function(S,i){S.goalLog.forEach(function(ev){goals.push({team:i,sit:ev.emptyNet?'EN':ev.sit,late:!!ev.late,scorer:id(ev.shooter),a1:id(ev.a1),a2:id(ev.a2),onIce:ids(ev.onIce),against:ids(ev.against)});});});
