    goals.filter(function(x){return x.sit==='SH';}).forEach(function(x){var opts=wins.filter(function(w){return w.team===x.team&&w.end-w.start>12;}),clean=opts.filter(function(w){return x.onIce.indexOf(w.player)<0;});var w=(clean.length?clean:opts)[Math.floor(rnd()*(clean.length||opts.length))];if(!w){x.sit='ES';return;}if(x.onIce.indexOf(w.player)>=0){var S0=sides[x.team],alt=S0.skaters.filter(function(p){return x.onIce.indexOf(p.id)<0;});var np=alt[Math.floor(rnd()*alt.length)];if(np){var op=S0.skaters.find(function(p){return p.id===w.player;});if(op)bumpPlayerStat(op,'penaltyMinutes',-2);bumpPlayerStat(np,'penaltyMinutes',2);w.player=np.id;}}var t=w.start+5;for(var k=0;k<40;k++){var c=w.start+5+rnd()*(w.end-w.start-9);if(free(c,6)){t=c;break;}}x.t=Math.round(t);});
    function inWindow(t,pad){return wins.some(function(w){return t>=w.start-pad&&t<=w.end+pad;});}
    var late=goals.filter(function(x){return x.late||x.sit==='EN';}),cut=late.length?R-125:R-6;
    goals.filter(function(x){return x.sit==='ES'&&!x.late;}).forEach(function(x){var t=null;for(var k=0;k<300&&t===null;k++){var c=8+rnd()*(cut-8),pc=c%P;if(pc<6||pc>P-3)continue;if(!inWindow(c,3)&&free(c,k<200?25:6))t=c;}if(t===null){t=8+rnd()*(cut-8);}x.t=Math.round(t);});
    var pull=null;
