  var AI_TYPE_LABEL={'contender buy':'CONTENDER BUY · SELLER CASHES IN','rebuild sell':'REBUILDER SELL · CONTENDER BUY','bubble rental':'BUBBLE RENTAL · SHORT-TERM HELP','retool sell':'RETOOL · VETERAN SOLD','retool buy':'RETOOL · YOUNGER NHL PLAYER ADDED','vet add':'YOUTH MOVEMENT · CHEAP VETERAN ADDED','youth sell':'YOUTH MOVEMENT · EXPIRING VETERAN SOLD','hockey trade':'HOCKEY TRADE · NEEDS SWAP','cap dump':'CAP DUMP · SALARY RELIEF','floor salary':'CAP FLOOR · SALARY TAKEN ON'};
