  function ahlKeepScore(p,role){var ovr=Number(p.ovr)||0,age=Number(p.age)||27;return ovr+(role==='REBUILD'||role==='YOUTH_MOVEMENT'?(age<=24?2:age>=30?-2:0):role==='RETOOL'?(age<=24?1:age>=31?-1:0):0)-(ahlStruggling(p)?1.5:0);}
  // 'Struggling' from the player's own season line (AI players have no hot/cold ledger; that is user-only).
  function ahlStruggling(p){if((Number(p.cold)||0)>=3)return true;var gp=Number(p.games)||0,ovr=Number(p.ovr)||70;if(p.pos==='G'){var sa=Number(p.goalieShotsAgainst)||0,st=Number(p.goalieStarts)||0;return st>=6&&sa>0&&1-(Number(p.goalieGoalsAgainst)||0)/sa<.885;}if(gp<15)return false;var ppg=(Number(p.points)||0)/gp,exp=p.pos==='D'?Math.max(.1,(ovr-70)*.025):Math.max(.15,(ovr-68)*.035);return ppg<exp*.5&&(Number(p.plusMinus)||0)<=-4;}
