      c.roster.push(p);p.club=id;p.reserveList=false;p.level='NHL';p.rosterStatus='Active roster · waiver claim';p.ahlMovedDate=date;p.waiverClaimedFrom=fromId;aiTenureMove(g,p,fromId,id);sc.n++;c.ahlWaiverClaims=sc;
      var text=team(id).name+' ('+role+') claim '+p.name+' ('+p.pos+', '+p.ovr+' OVR, '+shortMoney(hit)+') off waivers from '+team(fromId).name+'.';
      g.transactionLog=g.transactionLog||[];g.transactionLog.unshift({when:date+' · WAIVER CLAIM',text:text,teams:[id,fromId],tag:'WAIVER CLAIM'});g.transactionLog=g.transactionLog.slice(0,80);(g.history=g.history||[]).push({year:seasonLabel(g),text:text,tag:'WAIVER CLAIM'});
