  function setSyncProgress(done,total,label){var count=$('sync-progress-count'),bar=$('sync-progress-bar'),text=$('sync-progress-label');if(count)count.textContent=done+' / '+total;if(bar)bar.style.width=(total?Math.round(done/total*100):0)+'%';if(text)text.textContent=label||'Working…';}
