      if(!queue.length){var text='Finished: '+success+' teams added to starting data, '+empty+' empty, '+failed+' failed out of 32.\n'+summary.join('\n')+'\nCurrent franchises were not changed. '+(databasePersistent?'':'Starting-data changes are session-only: export them. ')+'API coverage is not verified. Empty results are not proof of an empty prospect pool. Old prospects/draft classes are not automatically removed.';setSyncProgress(attempted,32,failed||empty?'Finished with issues':'Requests finished - verify coverage');syncResult(text,failed>0||empty>0);return Promise.resolve();}
