  function showRuntimeError(message,error,filename,line,column){var box=$('fatal-message');if(!box)return;box.hidden=false;var detail=error&&(error.stack||error.message)||message||'Unknown script error';var source=filename?('\n'+filename+(line?':'+line+(column?':'+column:''):'')):'';$('fatal-detail').textContent='The app reported an error: '+String(detail)+source;}
  window.addEventListener('error',function(e){if(e&&e.target&&e.target!==window&&e.target.nodeType===1)return;/* v6: resource load failure, not a script error */showRuntimeError(e.message,e.error,e.filename,e.lineno,e.colno);},true);
