  function assignRosterPositionRole(g,id,role){var player=(g.roster||[]).find(function(p){return p.id===id;}),group=['LW','C','RW'].indexOf(role)>=0?'forwards':player&&player.pos==='D'&&['LD','RD'].indexOf(role)>=0?'defense':'';if(!player||!group||group==='forwards'&&['C','LW','RW'].indexOf(player.pos)<0)return false;ensureLineup(g);var rows=g.lines[group],slots=group==='forwards'?['LW','C','RW']:['LD','RD'],currentLine=rows.findIndex(function(row){return slots.some(function(slot){return row[slot]===id;});}),lineIndex=currentLine>=0?currentLine:rows.findIndex(function(row){return !row[role];});if(lineIndex<0)lineIndex=0;assignChartPlayer(group+'.'+lineIndex+'.'+role,id);player.linePositionRole=role;persist();renderOffice();if(officeUI.modal==='player-card')officeModalContent();setNotice(player.name+' assigned to '+role+' on '+team(g.team)+'’s lineup.');return true;}
