    var scheduleHtml=upcoming.map(function(id,i){var match=team(id),gameIndex=g.day+i,calendar=(g.calendarGames||[])[gameIndex],date=calendar&&calendar.date?new Date(calendar.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'GAME '+String(gameIndex+1).padStart(2,'0'),time=calendar&&calendar.startTimeUTC?new Date(calendar.startTimeUTC).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York'}):i===0?'NEXT':'—';return '<div class="home-schedule-item"><time>'+date+'</time>'+officeMark(id,'mini-crest')+'<strong>'+(calendar&&calendar.venue==='AWAY'?'@ ':'vs ')+esc(match.name)+'</strong><small>'+time+'</small></div>';}).join('')||'<p class="home-muted">The next schedule is set after the current round.</p>';
    var nextCalendar=(g.calendarGames||[])[g.day],nextDate=nextCalendar&&nextCalendar.date?new Date(nextCalendar.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'SIMULATED SCHEDULE',nextTime=nextCalendar&&nextCalendar.startTimeUTC?new Date(nextCalendar.startTimeUTC).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'}):'';
    var lastFiveHtml=lastFive.map(function(item){return '<i class="'+(item.result==='W'?'win':item.result==='L'?'loss':'other')+'">'+esc(item.result||'—')+'</i>';}).join('')||'<span class="home-muted">No completed games</span>';
    var expiring=(g.roster||[]).filter(function(p){return (p.years||0)<=1&&p.pos!=='G';}).sort(function(a,b){return (b.ovr||0)-(a.ovr||0);}),lowMorale=(g.roster||[]).filter(function(p){return Number(p.morale)<65;}).sort(function(a,b){return a.morale-b.morale;}),tasks=[];
