    var urgentNeed=officeNeeds(g,g.team).filter(function(need){return need.level==='High';})[0];if(urgentNeed)tasks.push({icon:'shield',title:'Roster priority: '+urgentNeed.label,detail:urgentNeed.detail,page:'roster'});
    tasks.push({icon:'calendar',title:hasNextMatch?'Prepare for next game':'Review offseason plan',detail:hasNextMatch?club.name+' vs '+opponent.name+' · Game '+String(Math.min(g.day+1,seasonGameCount(g))).padStart(2,'0'):'Draft, free agency and roster planning',page:hasNextMatch?'schedule':'frontoffice'});
