    $('office-content').innerHTML='<div class="home-dashboard"><section class="home-hero"><div class="home-hero-art"></div><div class="home-hero-club">'+officeMark(g.team,'home-hero-crest')+'<span><small>'+esc(g.team)+' · '+esc(club.division).toUpperCase()+'</small><strong>'+esc(club.name)+'</strong><em>HOCKEY OPERATIONS</em></span></div><div class="home-hero-title"><small>'+esc(seasonLabel(g))+' SEASON</small><strong>GENERAL MANAGER OFFICE</strong></div><div class="home-hero-status"><span class="home-hero-shield">'+officeIcon('shield')+'</span><span><small>FRANCHISE MODE</small><strong>'+esc(g.stage==='regular'?'REGULAR SEASON':g.stage==='playoffs'?'PLAYOFFS':'OFFSEASON')+'</strong></span></div></section><section class="home-card home-team-card"><header><span class="home-card-label">TEAM OVERVIEW</span><button class="home-more" data-ui-page="roster" aria-label="Open roster">↗</button></header><div class="home-team-lockup">'+officeMark(g.team,'home-crest')+'<span><strong>'+esc(club.name)+'</strong><small>'+esc(club.division)+' Division · '+rank+(rank===1?'st':rank===2?'nd':rank===3?'rd':'th')+'</small></span></div><div class="home-record"><span><strong>'+recordText(g.record)+'</strong><small>RECORD</small></span><span><strong>'+g.record.pts+'</strong><small>POINTS</small></span><span><strong>'+officeMoney(capRoom)+'</strong><small>CAP SPACE</small></span><span><strong>'+(teamMorale>=75?'GOOD':teamMorale>=60?'FAIR':'LOW')+'</strong><small>MORALE</small></span></div><div class="home-grades"><span><b>'+letterGrade(g.roster,'D')+'</b><small>DEFENSE</small></span><span><b>'+letterGrade(g.roster,'F')+'</b><small>OFFENSE</small></span><span><b>'+letterGrade(g.roster,'G')+'</b><small>GOALTENDING</small></span><span><b>'+letterGrade(g.roster,'ALL')+'</b><small>OVERALL</small></span></div><div class="home-cap"><div><strong>CAP HIT</strong><span>'+officeMoney(capUsed(g))+' <small> / '+officeMoney(g.cap)+'</small></span></div><div class="home-cap-track"><i style="width:'+Math.m