  function v4loyalSeedYears(p,teamId){var t=V4LOYAL_SEED[teamId];if(!t||!p)return 0;var k=v4fixKey(p.name),v=t[k+'|'+(p.birthDate||'')];if(v==null)v=t[k];return Number(v)||0;}
  function v4loyalCompleted(g){return Math.max(0,(Number(g&&g.season)||1)-1)+(g&&g.stage==='offseason'?1:0);}
  // THE reset hook: called with the club that currently holds the player.
  function v4loyalEnsure(g,p,teamId){if(!p||!teamId)return;if(p.orgTeam===teamId)return;
    if(p.orgTeam==null&&!p.v4LoyalSeeded){var s=v4loyalSeedYears(p,teamId);p.yearsWithOrg=s?s+v4loyalCompleted(g):0;p.v4LoyalSeeded=true;}
    else{p.yearsWithOrg=0;p.v4OrgCountedYear=null;}
    p.orgTeam=teamId;p.orgSince=g&&g.season?seasonLabel(g):'';}
  function v4loyalClubIds(g){return teams.map(function(t){return t.id;}).filter(function(id){return id===g.team||leagueClub(g,id);});}
  function v4loyalSyncAll(g){if(!g||!g.roster)return 0;var n=0;v4loyalClubIds(g).forEach(function(id){rosterPool(g,id).forEach(function(p){v4loyalEnsure(g,p,id);n++;});});v4loyalMarkMarket(g);return n;}
  // Read-only: never changes stored tenure. Pass the club that holds the player now; a club other than
  // p.orgTeam reads 0. Unseeded players read their seed value without storing it.
  function yearsWithOrg(g,p,teamId){if(!p)return 0;g=g||(current&&current.game);teamId=teamId||p.orgTeam;if(!teamId)return 0;var done;if(p.orgTeam==null&&!p.v4LoyalSeeded){var s=v4loyalSeedYears(p,teamId);done=s?s+v4loyalCompleted(g):0;}else if(p.orgTeam!==teamId)return 0;else done=Number(p.yearsWithOrg)||0;return done+(g&&g.stage==='offseason'?0:1);}
  function isLoyalToOrg(g,p,teamId){return yearsWithOrg(g,p,teamId)>=V4LOYAL_MIN;}
  function v4loyalDiscount(years){years=Number(years)||0;return years<V4LOYAL_MIN?0:Math.min(.15,.05+(years-V4LOYAL_MIN)*.0125);}
  function v4loyalCity(id){var n=team(id).name||'',w=n.split(' ');return /(Maple Leafs|Red Wings|Blue Jackets|Golden Knights)$/.test(n)?w.slice(0,-2).join(' '):w.slice(0,-1).join(' ')||n;}
  // Season end (called from beginOffseason before contracts expire): every signed player still with his
  // organization banks one more season of service.
  function v4loyalSeasonEnd(g){if(!g||!g.roster)return 0;var year=(Number(g.startYear)||2026)+(Number(g.season)||1);if(g.v4LoyalCountedYear===year)return 0;var n=0;
    v4loyalClubIds(g).forEach(function(id){var club=id===g.team?g:leagueClub(g,id);(club.roster||[]).concat(club.reserveRoster||[]).forEach(function(p){v4loyalEnsure(g,p,id);if(p.v4OrgCountedYear===year)return;p.yearsWithOrg=(Number(p.yearsWithOrg)||0)+1;p.v4OrgCountedYear=year;n++;});(club.orgProspects||[]).forEach(function(p){v4loyalEnsure(g,p,id);});});
    g.v4LoyalCountedYear=year;return n;}
  // FA market: tag pending free agents still held by a club they have served 8+ seasons.
  function v4loyalMarkMarket(g){(g.freeAgents||[]).forEach(function(slot){var src=slot.external?null:clubRoster(g,slot.sourceTeam),p=src&&src.find(function(x){return x.id===slot.playerId;});if(!p){var q=(g.currentFreeAgentPool||[]).find(function(x){return x.id===slot.playerId;});if(q)delete q.v4LoyalHome;return;}v4loyalEnsure(g,p,slot.sourceTeam);var yrs=yearsWithOrg(g,p,slot.sourceTeam);if(yrs>=V4LOYAL_MIN)p.v4LoyalHome={team:slot.sourceTeam,years:yrs,discount:v4loyalDiscount(yrs)};else delete p.v4LoyalHome;});}
  function v4loyalHome(p,teamId){var h=p&&p.v4LoyalHome;return h&&h.team===teamId?h:null;}
  // Clear decline candidates and low-value players get no loyalty push: the club can let them walk.
  function v4loyalDecline(p,pct){var age=Number(p.age)||27,ovr=Number(p.ovr)||70;return (age>=36&&ovr<84)||(age>=33&&ovr<76)||(pct!=null&&pct<.35);}
  // Pre-market (June 30) own-club re-signing for AI clubs.
  function v4loyalPreMarket(g,p,teamId,pct){var yrs=yearsWithOrg(g,p,teamId),d=v4loyalDiscount(yrs);if(!d||v4loyalDecline(p,pct))return {allow:false,prob:0,mult:1,years:yrs};var age=Number(p.age)||27;p.v4LoyalOffer={team:teamId,years:yrs,discount:d};return {allow:age<=37||(Number(p.ovr)||70)>=88,prob:.25+Math.min(.12,(yrs-V4LOYAL_MIN)*.015)+(age>=33?.1:0),mult:1-d,years:yrs};}
  function v4loyalRfaSalary(g,p,teamId,salary,qo){var yrs=yearsWithOrg(g,p,teamId),d=v4loyalDiscount(yrs);if(!d)return salary;p.v4LoyalOffer={team:teamId,years:yrs,discount:d};return Math.max(qo,Math.round(salary*(1-d)/25000)*25000);}
  // Market: home club's daily bid chance / price, and the player's preference when he scores offers.
  function v4loyalBidBoost(g,p,teamId){return v4loyalHome(p,teamId)&&!v4loyalDecline(p)?25:0;}
  function v4loyalHomeMult(g,p,teamId){var h=v4loyalHome(p,teamId);return h?1-h.discount:1;}
  function v4loyalOfferBonus(g,p,offer,ask){var h=v4loyalHome(p,offer&&offer.team);if(!h)return 0;var a=Math.max(1,Number(ask)||1);if(Number(offer.salary)<a*(1-h.discount-.08))return 0;return 58*h.discount+4;}
  // Boston extensions: discounted ask and a better chance of agreement when the offer is fair.
  function v4loyalExtBoost(g,p,ratio){if(!g||(g.roster||[]).indexOf(p)<0)return 0;var yrs=yearsWithOrg(g,p,g.team);if(yrs<V4LOYAL_MIN||ratio<.95)return 0;return .1+Math.min(.08,(yrs-V4LOYAL_MIN)*.01);}
  function v4loyalBadge(g,p,teamId){var yrs=yearsWithOrg(g,p,teamId||g.team);return yrs>=V4LOYAL_MIN?' · <b class="v4-loyal" style="color:#ffbf17" title="'+yrs+' straight seasons with the organization: prefers to re-sign and will take a hometown discount (about '+Math.round(v4loyalDiscount(yrs)*100)+'%).">Loyal ('+yrs+' yrs)</b>':'';}
  function v4loyalWants(g,p,teamId){teamId=teamId||g.team;return isLoyalToOrg(g,p,teamId)?'Wants to stay in '+v4loyalCity(teamId):'';}
  function v4loyalFaHome(g,p,slot){return slot&&!slot.external?v4loyalHome(p,slot.sourceTeam):null;}
  function v4loyalFaTag(g,p,slot){var h=v4loyalFaHome(g,p,slot);return h?' <i class="fa-status v4-loyal" title="'+h.years+' straight seasons with '+esc(team(h.team).name)+'">LOYAL '+h.years+' YRS</i>':'';}
  function v4loyalFaNote(g,p,slot){var h=v4loyalFaHome(g,p,slot);return h?'<small class="v4-loyal-note">'+(h.team===g.team?'Wants to stay in '+esc(v4loyalCity(h.team))+': open to a hometown discount of about '+Math.round(h.discount*100)+'%':'Prefers to stay with '+esc(team(h.team).name)+'; rivals must clearly outbid')+'</small>':'';}
  // Called from completeFreeAgentSigning: a signing with a new club restarts tenure; a home re-sign is recorded.
  function v4loyalOnSign(g,p,teamId,sameClub){var h=p.v4LoyalHome;if(sameClub&&h&&h.team===teamId)p.v4LoyalResign={team:teamId,years:h.years,discount:h.discount,season:seasonLabel(g),via:'market'};delete p.v4LoyalHome;if(!sameClub)v4loyalEnsure(g,p,teamId);}
  function v4loyalExtNote(g,p,accepted,ratio){if(!g||(g.roster||[]).indexOf(p)<0)return '';var yrs=yearsWithOrg(g,p,g.team);if(yrs<V4LOYAL_MIN)return '';var city=v4loyalCity(g.team);if(accepted){p.v4LoyalResign={team:g.team,years:yrs,discount:v4loyalDiscount(yrs),season:seasonLabel(g),via:'extension'};return ' Loyal ('+yrs+' yrs): he wanted to stay in '+city+' and took a hometown discount.';}return ratio<.95?' He wants to stay in '+city+', but not at that price.':' He still wants to stay in '+city+'; a fair offer near his ask should get it done.';}
