  /* ---------- draft records, grades, redraft ---------- */
  function scDraftRec(S,y){var R=S.drafts.filter(function(d){return d.y===y;})[0];if(!R){R={y:y,p:[],gr:null,rd:null,war:null};S.drafts.push(R);if(S.drafts.length>8)S.drafts.shift();}return R;}
  function scSnap(g,S){var R=scDraftRec(S,S.year);if(R.snap)return;var list=scClassList(g).slice().sort(function(a,b){return scPub(b)-scPub(a);});R.snap=list.map(function(p){return Math.round(scPub(p)*10)/10;});
    if(S.war)R.war={over:S.war.over,backed:S.war.backed,pitches:S.war.pitches.map(function(x){return [x.sid,x.pid,x.st||'',x.ask];})};}
