  document.addEventListener('click',function(ev){var el=ev.target&&ev.target.closest&&ev.target.closest('[data-sc]');if(!el||!el.closest('.sc2'))return;ev.preventDefault();try{scAct(el);}catch(e){if(window.console)console.error('scouting',e);}});
