  function scPlayerCard(id){var g=scG0();if(!g)return;var p=scFindPlayer(g,id);if(!p||!p.scFile)return;var m=document.getElementById('workspace-modal');if(!m||m.querySelector('.sc2-file'))return;var t=m.querySelector('.roster-player-modal')||m.querySelector('#workspace-modal-body')||m.querySelector('.workspace-dialog')||m;if(!t)return;var before=t.querySelector('.roster-player-actions,.player-file-development');if(before)before.insertAdjacentHTML('beforebegin',scFileHtml(g,p));else t.insertAdjacentHTML('beforeend',scFileHtml(g,p));}

