  scWrap('advanceSeason',function(){return advanceSeason;},function(f){advanceSeason=f;},function(o){return function(g){var before=g&&g.season,r=o.apply(this,arguments);try{if(g&&g.season!==before){var S=scEnsure(g);S.drafts.forEach(function(R){if(!R.rd&&R.gr&&scDraftYear(g)-R.y>=SC.REDRAFT_AFTER)scRedraft(g,S,R,false);});}}catch(e){console.error('scouting season',e);}return r;};});
  scWrap('progressPlayerOffseason',function(){return progressPlayerOffseason;},function(f){progressPlayerOffseason=f;},function(o){return function(p,teamId,g){var r=o.apply(this,arguments);try{if(p&&p.ctfoTraits&&p.drafted&&(+p.age||30)<=22){var t=p.ctfoTraits,wk=(t.cmp+t.coa)/2,x=scR('sc-dev|'+p.id+'|'+(g&&g.season));if(wk>=68&&x<.35)p.ovr=Math.min(+p.potential||99,(+p.ovr)+1);else if(wk<=32&&x<.3)p.ovr=Math.max(40,(+p.ovr)-1);}}catch(e){}return r;};});
  scWrap('officeOpenModal',function(){return officeOpenModal;},function(f){officeOpenModal=f;},function(o){return function(kind,side){var r=o.apply(this,arguments);if(kind==='player-card'){try{scPlayerCard(side);}catch(e){}}return r;};});
  /* trades (light): YOUR valuation of other clubs' young prospects uses your scouting file or the public read, not hidden truth */
