      if(io)scWrap('initializeDraftOrder',function(){return initializeDraftOrder;},function(f){initializeDraftOrder=f;},function(){return io;});
      /* every way into a pick: one pick, sim to mine, sim all / finish, your pick (manual or auto), draft trades */
      var e1=wd('advanceDraftOnePick',scEntry);if(e1)scWrap('advanceDraftOnePick',function(){return advanceDraftOnePick;},function(f){advanceDraftOnePick=f;},function(){return e1;});
      var e2=wd('advanceDraftToUserPick',scEntry);if(e2)scWrap('advanceDraftToUserPick',function(){return advanceDraftToUserPick;},function(f){advanceDraftToUserPick=f;},function(){return e2;});
      var e3=wd('finishDraft',scEntry);if(e3)scWrap('finishDraft',function(){return finishDraft;},function(f){finishDraft=f;},function(){return e3;});
