      /* AI valuations asked for outside a pick (draft-trade offers etc.) also use that club's own board */
      var ap=wd('aiDraftPickScore',function(n,o){return function(g,clubId,p){var S=g&&g.scouting;if(!S||!p||clubId===g.team||scRowSwap)return o.apply(this,arguments);var sp=p.projection;p.projection=Math.round(scAiValue(g,S,clubId,p)*10)/10;try{return o.apply(this,arguments);}finally{p.projection=sp;}};});
      if(ap)scWrap('aiDraftPickScore',function(){return aiDraftPickScore;},function(f){aiDraftPickScore=f;},function(){return ap;});
