    read:function(g,p){var S=scEnsure(g);if(!S)return null;var R=scRead(S,p);return {tier:R.T,known:Math.round(R.K),potLow:R.lo,potHigh:R.hi,ovrLow:R.olo,ovrHigh:R.ohi,character:R.I?R.I.ch:{},medical:R.I&&R.I.med&&p.scT?scInjLabel(p.scT.inj):null,boom:!!(R.I&&R.I.boom)};},
